template:
fn keep_positives(v: &mut Vec<i32>) {
    v.⟦method⟧(|⟦param⟧| x > 0);
}

fn main() {
    let mut nums = vec![-2, 5, 0, 3];
    keep_positives(&mut nums);
    println!("{:?}", nums);
}

tests:
#[test]
fn keeps_only_positive() {
    let mut v = vec![-2, 5, 0, -1, 3];
    keep_positives(&mut v);
    assert_eq!(v, vec![5, 3]);
}
